/**
 * Help Scout webhook verification + parsing, per the Webhooks reference
 * (fetched 2026-09-28): https://developer.helpscout.com/webhooks/
 *
 * "Each webhook includes two Help Scout headers: X-HelpScout-Event: Lists the
 * event name ... X-HelpScout-Signature: The computed signature generated by
 * Help Scout." "Signatures are calculated based on the raw request body passed
 * to your servers by Help Scout." Reference (PHP):
 *   base64_encode(hash_hmac('sha1', $data, WEBHOOK_SECRET_KEY, true))
 *
 * The secret is the key the customer types into the Webhooks app (Settings >
 * Workspace > Apps > Webhooks); it reaches us as the per-connection webhook
 * secret or the static adapter secret, like every other handler. No timestamp
 * is sent, so no replay window can be checked; retries ("up to 10 times")
 * mean duplicates are expected.
 *
 * Published vector (Ruby example on that page): secret "your secret key",
 * body '{"ticket":{"id":"1","number":"2"},...}' -> 'I1KlvGppYqvFTJgJ9jezdQMDiyI='.
 * The page's older '+oNIxipGoqx4t2BmkBHbXKc6VHM=' does NOT reproduce.
 */
import { createHmac, timingSafeEqual } from 'node:crypto'
import type { WebhookHandler } from '@opensteward/shared'
import type { WebhookAction, WebhookEvent, WebhookResourceType } from '../../schema/webhook'

function header(headers: Record<string, string>, name: string): string | undefined {
  const want = name.toLowerCase()
  for (const [k, v] of Object.entries(headers)) {
    if (k.toLowerCase() === want && typeof v === 'string') return v
  }
  return undefined
}

export function verifyHelpScoutWebhook(
  payload: Buffer,
  headers: Record<string, string>,
  secret: string,
): boolean {
  try {
    if (!secret) return false
    const provided = header(headers, 'x-helpscout-signature')?.trim()
    if (!provided) return false
    const expected = createHmac('sha1', secret).update(payload).digest('base64')
    const a = Buffer.from(expected, 'utf8')
    const b = Buffer.from(provided, 'utf8')
    if (a.length !== b.length) return false
    return timingSafeEqual(a, b)
  } catch {
    return false
  }
}

type Mapped = { resourceType: WebhookResourceType; action: WebhookAction }

/** Event names from the "Available Events" table; anything else is unknown/unknown. */
const EVENT_MAP: Record<string, Mapped> = {
  'convo.assigned': { resourceType: 'tickets', action: 'assigned' },
  'convo.created': { resourceType: 'tickets', action: 'created' },
  'convo.ai-answers.created': { resourceType: 'tickets', action: 'created' },
  'convo.deleted': { resourceType: 'tickets', action: 'deleted' },
  'convo.merged': { resourceType: 'tickets', action: 'updated' },
  'convo.moved': { resourceType: 'tickets', action: 'updated' },
  'convo.status': { resourceType: 'tickets', action: 'updated' },
  'convo.tags': { resourceType: 'tickets', action: 'updated' },
  'convo.custom-fields': { resourceType: 'tickets', action: 'updated' },
  // Reply/note events carry the v2 Conversation object, not the thread.
  'convo.customer.reply.created': { resourceType: 'messages', action: 'commented' },
  'convo.agent.reply.created': { resourceType: 'messages', action: 'commented' },
  'convo.note.created': { resourceType: 'messages', action: 'commented' },
  'customer.created': { resourceType: 'contacts', action: 'created' },
  'customer.updated': { resourceType: 'contacts', action: 'updated' },
  'customer.deleted': { resourceType: 'contacts', action: 'deleted' },
  'satisfaction.ratings': { resourceType: 'tickets', action: 'rated' },
  'tag.created': { resourceType: 'tags', action: 'created' },
  'tag.updated': { resourceType: 'tags', action: 'updated' },
  'tag.deleted': { resourceType: 'tags', action: 'deleted' },
}

const UNKNOWN: Mapped = { resourceType: 'unknown', action: 'unknown' }

/**
 * The event name travels ONLY in the X-HelpScout-Event header, so it needs the
 * request headers: the unified router calls parseWebhookEventsWithHeaders.
 * Called through parseWebhookEvents (body alone), every event parses as
 * unknown/unknown with the body id kept.
 *
 * resourceId: the body is a v2 object whose top-level `id` is that object's
 * id (or `{id}` for delete events). satisfaction.ratings carries a v2 Rating
 * object, whose `id` is the RATING id; the rated conversation is its
 * `conversationId`, so that is what a tickets/rated event points at.
 * https://developer.helpscout.com/mailbox-api/endpoints/ratings/get/
 */
export function parseHelpScoutWebhookEvents(
  payload: Record<string, unknown>,
  headers: Record<string, string> = {},
): WebhookEvent[] {
  const type = header(headers, 'x-helpscout-event') ?? ''
  const mapped = EVENT_MAP[type] ?? UNKNOWN
  const str = (v: unknown): string => (v == null ? '' : String(v))
  const id = str(payload['id'])
  const resourceId = type === 'satisfaction.ratings' ? str(payload['conversationId']) || id : id
  return [
    {
      id: `helpscout:${type || 'unknown'}:${id}`,
      platform: 'helpscout',
      type,
      resourceType: mapped.resourceType,
      action: mapped.action,
      resourceId,
      ticketId: mapped.resourceType === 'messages' ? id : undefined,
      payload,
    },
  ]
}

export const HelpScoutWebhookHandler: WebhookHandler = {
  verifyWebhook: verifyHelpScoutWebhook,
  parseWebhookEvents: (payload) => parseHelpScoutWebhookEvents(payload),
  parseWebhookEventsWithHeaders: parseHelpScoutWebhookEvents,
}
